    def select_path(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')

        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.Directory)

        self.file_dialog = file_dialog.exec()
        
        if self.file_dialog == QtWidgets.QFileDialog.DialogCode.Accepted:

            self.path = file_dialog.selectedFiles()[0]
        
    def select_csv(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')

        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.ExistingFile)

        file_dialog.setNameFilter("Arquivos CSV (*.csv);;Todos os arquivos (*)")

        self.file_dialog_csv = file_dialog.exec()

        if self.file_dialog_csv == QtWidgets.QFileDialog.DialogCode.Accepted:

            self.path  = file_dialog.selectedFiles()[0]

    def get_resolution(self, resolution, unit):
    
        if unit == 'nm':
            
            resolution = resolution/1000
            
        return resolution

    def dm4_to_csv(self):

        if self.file_dialog == QtWidgets.QFileDialog.DialogCode.Accepted:
        
            myData = list()

            files = os.listdir(self.path) # list the image files in the path

            for image in files: # loop through the image files

                load_in = os.path.join(self.path, image) # path to the image

                if (image.endswith(".dm3") or image.endswith(".dm4")):
                            
                    dm4_file = dm.dmReader(load_in) #read the dm3 file

                    image_name = os.path.splitext(image)[0]
                    
                    dm4_file.pop('data')

                    resolution = self.get_resolution(dm4_file['pixelSize'][0],dm4_file['pixelUnit'][0])
        
                    dm4_file['TEM image'] = str(self.path + '_' + image_name +'.png')
                    dm4_file['coords'] = dm4_file['coords'][0]
                    dm4_file['pixelSize'] = str(dm4_file['pixelSize'][0])
                    dm4_file['pixelUnit'] = str(dm4_file['pixelUnit'][0])
                    dm4_file['resolution (µm)'] = str(resolution)
                    dm4_file['file_path'] = self.path

                    myData.append(dm4_file)

            df = pd.DataFrame(myData)

            try:

                os.mkdir(self.path + '/datasette/')

            except: pass

            df.to_csv(self.path + '/datasette/dm4_images.csv', index=False, header=True)  

            self.labelPrints.setText("CSV saved at: " + self.path + '/datasette/dm4_images.csv')

        else: pass

    def create_db_file(self):
        
        if self.file_dialog == QtWidgets.QFileDialog.DialogCode.Accepted:
            
            if os.name == 'nt':
                sqlite_utils_path = os.path.join(basedir, "datasette", "sqlite-utils.exe")
            
            else:
                sqlite_utils_path = "sqlite-utils"
            
            db_path = f"{self.path}/datasette/dm4_images.db"
            
            csv_path = f"{self.path}/datasette/dm4_images.csv"
            
            # Create .bd file from csv
            subprocess.run([sqlite_utils_path, "insert", db_path, "dm4_images", csv_path, "--csv"])

            #self.labelDatasetteAddress.clear()

            self.labelDatasetteAddress.appendPlainText(".db saved at: " + self.path + '/datasette/dm4_images.db')

            # Start datasette process
            self.process = QtCore.QProcess(self)

            if os.name == 'nt':
                
                datasette_path = os.path.join(basedir, "datasette", "datasette.exe")
            
            else:
                
                datasette_path = "datasette"
            
            self.labelDatasetteAddress.appendPlainText('starting')
            self.process.start(datasette_path, [self.path + "/datasette/dm4_images.db"])
            self.labelDatasetteAddress.appendPlainText('started')
            self.process.readyReadStandardOutput.connect(self.handle_stdout)
            self.process.readyReadStandardError.connect(self.handle_stderr)

        else: pass

    def create_db_file_from_csv(self):
        
        if self.file_dialog_csv == QtWidgets.QFileDialog.DialogCode.Accepted:

            # Get .csv path

            csv_directory = os.path.split(self.path)[0]

            # Check if it's running on windows or linux
            if os.name == 'nt':
                # For windows, need the .exe path
                sqlite_utils_path = os.path.join(basedir, "datasette", "sqlite-utils.exe")
                # Create .bd file from csv
                #subprocess.run([sqlite_utils_path, "insert", csv_directory + "/dm4_images.db", "dm4_images", self.path, "--csv"])
            
            else:
                sqlite_utils_path = "sqlite-utils"
            
            db_path = f"{csv_directory}/dm4_images.db"
            
            csv_path = f"{self.path}"
                
                # Create .bd file from csv
            subprocess.run([sqlite_utils_path, "insert", db_path, "dm4_images", csv_path , "--csv"])
            
            if os.name == 'nt':
                
                datasette_path = os.path.join(basedir, "datasette", "datasette.exe")
            
            else:
                
                datasette_path = "datasette"
            
            # Start datasette process
            self.process = QtCore.QProcess(self)
            self.labelDatasetteAddress.clear()
            self.process.start(datasette_path, [csv_directory + "/dm4_images.db"])
            self.process.readyReadStandardOutput.connect(self.handle_stdout)
            self.process.readyReadStandardError.connect(self.handle_stderr)

        else: pass

    def handle_stdout(self):
        data = self.process.readAllStandardOutput().data().decode()
        self.labelDatasetteAddress.appendPlainText(data)

    def handle_stderr(self):
        data = self.process.readAllStandardError().data().decode()
        self.labelDatasetteAddress.appendPlainText(data)

    def stop_process(self):

        try: #Consider button pressed when no process was initiated

            if self.process.state() == QtCore.QProcess.ProcessState.Running:
                self.process.terminate()
                if not self.process.waitForFinished(3000):  # Wait up to 3 seconds for process to terminate
                    self.process.kill()  # Force kill if it doesn't terminate

                self.labelDatasetteAddress.appendPlainText("Process Terminated.")

            else:
                self.labelDatasetteAddress.appendPlainText("No Process Running.")
                
        except: pass

